        "ja": "モンゴルへ行ったらしっかり活動するために、毎日しっかり学ぶ必要があります。そのため毎日モンゴル語で話す練習をしています。",
        "romaji": "Bi Mongold ochood sain ajillakhyn tuld odor bur sain surakh kheregtei. Tiim uchraas odor bur mongol kheleer yarikh dasgal khiideg.",
