    "icon": "🏥",
    "title": "病院にて",
    "titleJa": "病院での診察・症状の伝達",
    "titleMn": "Эмнэлэгт",
    "description": "医師との診察対話：頭痛の症状、発熱（38度）、喉の痛み、口を開けての診察、解熱鎮痛剤の処方と食後1日3回の服用指示。",
    "examinerPromptMn": "Та эмнэлэгт очвол, эмчтэй юу гэж ярих вэ?",
    "examinerPromptJa": "病院に行ったら、医師とどのように話しますか？",
    "targetTimeSeconds": 45,
    "fullTextMn": "Эмч： Сайн байна уу? Та энэ сандал дээр суугаарай.\nБи： Сайн байна уу? Маш их баярлалаа, эмч ээ.\nЭмч： За, таны бие яаж байна? Биеийн хаана чинь өвдөж байна вэ?\nБи： Миний толгой маш их өвдөж байна.\nЭмч： Толгойн өвдөлт хэзээнээс эхэлсэн бэ? Өчигдөр үү, уржигдар уу?\nБи： Өчигдөр оройноос эхэлж өвдсөн. Шөнө унтаж чадсангүй.\nЭмч： Халуурч байна уу? Гэртээ халуунаа үзэж ирсэн уу?\nБи： Тийм ээ, өглөө халуунаа үзэхэд, 38 градус  байсан.\nЭмч： Хоолой чинь ч бас өвдөж байна уу?\nБи： Тийм ч өвдөхгүй байна. Гэхдээ юм уухад, хоолой жаахан өвдөж байна.\nЭмч： Ойлголоо. За, амаа том нээгээрэй. Хоолой чинь жаахан улаан гэж бодож байна.\nБи： Би ямар нэгэн эм ууж болох уу? Би хурдан эдгэрэхийг хүсэж байна.\nЭмч： Тийм ээ. Би танд толгойн өвчин намдаах эм өгье.\nБи： Их баярлалаа. Энэ эмийг өдөрт хэдэн удаа, яаж уух ёстой вэ?\nЭмч： Энэ эмийг хоолны дараа өдөрт гурван удаа усаар уугаарай. Сайн амраарай.",
    "fullTextJa": "こんにちは。この椅子にお掛けください。 こんにちは。どうもありがとうございます、先生。 さて、体の具合はいかがですか？ お体のどこが痛みますか？ 頭がひどく痛みます。 頭痛はいつから始まりましたか？ 昨日ですか、一昨日ですか？ 昨日の晩から痛み始めました。夜は眠れませんでした。 熱はありますか？ 家で熱を測って来ましたか？ はい、今朝熱を測ったら38度ありました。 喉も痛みますか？ それほど痛くはありません。でも物を飲む時に喉が少し痛みます。 分かりました。はい、お口を大きく開けてください。喉が少し赤くなっているようですね。 何か薬を飲んでもいいですか？ 早く治りたいです。 はい。あなたに鎮痛剤（頭痛を和らげる薬）を出しましょう。 どうもありがとうございます。この薬は1日何回、どのように飲むべきですか？ この薬を食後に1日3回、お水で飲んでください。お大事に、しっかり休んでくださいね。",
