    "fullTextMn": "Зочид буудлын ажилтан： Сайн байна уу? Танд юу хэрэгтэй вэ?\nҮйлчлүүлэгч： Сайн байна уу? Би нэг хономоор байна. Нэг ортой өрөө байна уу?\nЗочид буудлын ажилтан： Тийм ээ, байна. Манайд нэг ортой өрөө байгаа.\nҮйлчлүүлэгч： За, баярлалаа. Нэг хоног нь хэдэн төгрөг вэ?\nЗочид буудлын ажилтан： Нэг хоног нь 50,000 төгрөг.\nҮйлчлүүлэгч： За, би нэг орой хононо. Өрөөнд өглөөний цай байгаа юу?\nЗочид буудлын ажилтан： Тийм ээ, өглөөний цай үнэгүй.\nҮйлчлүүлэгч： Сайхан байна. Өглөөний хоол хэдэн цагт вэ?\nЗочид буудлын ажилтан： Өглөөний хоол 6:30-аас 8:30 хүртэл.\nҮйлчлүүлэгч： За, ойлголоо. Би хэдэн цагт өрөөндөө орж болох вэ?\nЗочид буудлын ажилтан： Та 14:00 цагаас өрөөндөө орж болно.\nҮйлчлүүлэгч： За. Би одоо өрөөндөө орж болох уу?\nЗочид буудлын ажилтан： Уучлаарай, одоо өрөө бэлэн биш байна. Та түр хүлээгээрэй.\nҮйлчлүүлэгч： За, асуудалгүй. Би картаар төлж болох уу?\nЗочид буудлын ажилтан： Бололгүй  яах вэ. Картаар төлж болно.Төлбөр хийхийн өмнө энэ цаасан дээр нэр, хаяг, утасны дугаараа бичээрэй.\nҮйлчлүүлэгч： За, бичсэн. Дараа нь картаар төлнө. Баярлалаа.\nЗочид буудлын ажилтан： Баярлалаа. Энэ таны өрөөний түлхүүр. Таны өрөө 110-р өрөө. Сайхан амраарай",
    "fullTextJa": "いらっしゃいませ。ご用件をお伺いします。 こんにちは。1泊したいのですが。シングルの部屋はありますか？ はい、ございます。シングルのお部屋が空いております。 ありがとうございます。1泊いくらですか？ 1泊50,000トゥグルグです。 では、1泊泊まります。部屋代に朝食は付いていますか？ はい、朝食は無料です。 それは良いですね。朝食は何時からですか？ 朝食は6時半から8時半までです。 分かりました。何時にお部屋に入れますか（チェックインできますか）？ 14時からお部屋にお入りいただけます。 分かりました。今すぐ部屋に入ることはできますか？ 申し訳ありません、現在お部屋の準備ができておりません。少々お待ちください。 はい、問題ありません。カードで支払えますか？ もちろんですとも。カードでお支払いいただけます。お支払いの前に、こちらの用紙にお名前、ご住所、電話番号をご記入ください。 はい、書きました。それではカードで支払います。ありがとうございます。 ありがとうございます。こちらがお部屋の鍵です。お部屋は110号室です。ごゆっくりお過ごしください。",
